use std::num::ParseIntError;
use std::time::Duration;

/// Parse a decimal millisecond duration.
pub fn parse_millis(s: &str) -> Result<Duration, ParseIntError> {
    let millis: u64 = s.parse()?;
    Ok(Duration::from_millis(millis))
}

